 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);widgetRequestPending=intent.hasExtra(GoalPlannerWidget.EXTRA_ITEM);if(!busy)refresh();}
 private void handleWidgetRequest()throws Exception {
  widgetRequestPending=false;Intent intent=getIntent();if(snapshot==null||planning==null||planning.isNull("plan")||intent.getLongExtra(GoalPlannerWidget.EXTRA_STATE,-1)!=snapshot.getLong("revision")||intent.getLongExtra(GoalPlannerWidget.EXTRA_REVISION,-1)!=planning.optLong("plan_revision",-2)){notice.setText("安排已更新，已显示最新状态。请重新选择行动。");return;}
  JSONObject requested=new JSONObject(intent.getStringExtra(GoalPlannerWidget.EXTRA_ITEM)),selected=null;JSONArray items=GoalPlannerWidget.items(planning.getJSONObject("plan"));for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);if(item.getInt("slot")==requested.optInt("slot",-1)&&item.optString("action_id").equals(requested.optString("action_id"))&&item.optString("entity").equals(requested.optString("entity"))&&item.optBoolean("reservation")==requested.optBoolean("reservation")){selected=item;break;}}
  if(selected==null){notice.setText("这项安排已经失效，请选择最新行动。");return;}final JSONObject item=selected;
  Runnable result=()->{try{if(item.getInt("slot")!=snapshot.getInt("game_slot")){setup();notice.setText("这是未来时段的安排。先核对并更新当前实际日期与资源，再记录结果。");return;}if(item.optString("kind").equals("resources")){setup();notice.setText("请填写打工后的实际余额与当前日期，系统会据此重排。");return;}resultKind=item.optString("kind","social");resultEntity=item.optString("entity",item.optString("entity_id",""));resultForm();}catch(Exception e){notice.setText(e.getMessage());}};
  if(intent.getBooleanExtra(GoalPlannerWidget.EXTRA_RESULT,false)&&item.getInt("slot")==snapshot.getInt("game_slot")){result.run();return;}
  container();label(GameDate.label(item.getInt("slot")),22);label(item.getString("title"),24);notice=label(item.optBoolean("reservation")?"这是补充会面预留。先看游戏提示，再按实际结果继续。":"按这项安排进行；结束后填写实际结果。",15);label(actionDetails(planning.getJSONObject("plan"),item.optString("action_id"),item),14);button("记录这个行动的实际结果",result);button("返回全部安排",()->{try{home();}catch(Exception e){notice.setText(e.getMessage());}});
 }
 private void submit(String path,JSONObject body){try{synchronized(COMMAND_LOCK){if(receipts.contains("pending"))throw new IllegalArgumentException("请先处理尚未确认的提交");body.put("command_id",UUID.randomUUID().toString());JSONObject pending=new JSONObject().put("path",path).put("body",body);if(!receipts.edit().putString("pending",pending.toString()).commit())throw new IllegalStateException("无法保存提交标识");execute(pending);}}catch(Exception e){notice.setText(e.getMessage());}}
 private void retry(){try{String value=receipts.getString("pending",null);if(value!=null)execute(new JSONObject(value));}catch(Exception e){notice.setText(e.getMessage());}}
 private void execute(JSONObject pending){setBusy(true);worker.execute(()->{try{String path=pending.getString("path");JSONObject body=pending.getJSONObject("body"),response=coordinator.request(path,body.toString());synchronized(COMMAND_LOCK){JSONObject active=new JSONObject(receipts.getString("pending","{}"));if(active.optJSONObject("body")!=null&&body.getString("command_id").equals(active.getJSONObject("body").optString("command_id"))){SharedPreferences.Editor edit=receipts.edit().remove("pending");if(path.equals("/api/setup")||path.equals("/api/baseline"))edit.remove("last_return");if(path.equals("/api/setup"))edit.remove("setup_draft").remove("setup_draft_revision").putBoolean("setup_open",false);if(path.equals("/api/return"))edit.putString("last_return",new JSONObject().put("original_id",body.optString("corrects_event_id",body.getString("command_id"))).put("body",body).put("epoch",response.getJSONObject("observation").getJSONObject("snapshot").getLong("epoch")).toString());edit.commit();}}
    runOnUiThread(()->{if(destroyed)return;setBusy(false);refresh();});
  }catch(Exception e){runOnUiThread(()->{if(destroyed)return;setBusy(false);notice.setText("提交尚未确认："+e.getMessage()+"。返回首页后可重试原提交并核对状态。");});}});}
 private void setBusy(boolean value){busy=value;if(activeForm!=null)activeForm.setInputsEnabled(!value);for(View control:controls)control.setEnabled(!value);}
 private String display(JSONObject object,String key){return object.isNull(key)?"未知":object.optString(key,"未知");}
 private String goalName(String field){String slug=field.replace("socialLinks.","").replace(".rank","");return names.getOrDefault(slug,field);}
 private void renderPlan()throws Exception{label("接下来的安排",22);if(planning==null||planning.isNull("plan")){label("先确认当前状态与目标",16);return;}JSONObject plan=planning.getJSONObject("plan");String status=plan.optString("status");label(status.equals("conditional")?"保守安排 · 按实际结果调整":status.equals("unknown")?"保守规划 · 部分后续需按实际结果调整":status.equals("unsupported")?"部分规则暂未覆盖":status.equals("search_limit")?"本轮搜索达到计算上限":status,18);
  JSONArray unsupported=plan.optJSONArray("unsupported_goals");if(unsupported!=null&&unsupported.length()>0){StringBuilder text=new StringBuilder("尚未覆盖的目标：");for(int i=0;i<unsupported.length();i++)text.append(goalName(unsupported.getJSONObject(i).getString("field"))).append(' ');label(text.toString(),14);}
  JSONArray blocked=plan.optJSONArray("goals_needing_observation");if(blocked!=null)for(int i=0;i<blocked.length();i++){JSONObject item=blocked.getJSONObject(i);label(goalName(item.getJSONObject("goal").getString("field"))+"："+item.getString("reason"),14);}
  JSONArray checks=plan.optJSONArray("observation_checkpoints");
  JSONObject metadata=plan.optJSONObject("action_metadata");JSONArray steps=plan.optJSONArray("steps");int count=0;if(steps!=null)for(int i=0;i<steps.length();i++){JSONObject step=steps.getJSONObject(i);String id=step.getString("action_id");if(id.equals("__wait__"))continue;JSONObject detail=metadata==null?null:metadata.optJSONObject(id);String title=detail==null?id.equals("p3r.action.visit_sun")?"太阳社群会面":id.equals("p3r.action.visit_devil")?"恶魔社群会面":id.contains("explore")?"探索塔尔塔罗斯，回来填写实际结果":id:detail.optString("display_title",detail.optString("title",id));label(GameDate.label(step.getInt("slot"))+"\n"+title,16);count++;}
  JSONArray reservations=plan.optJSONArray("adaptive_reservations");if(reservations!=null)for(int i=0;i<reservations.length();i++){JSONObject reservation=reservations.getJSONObject(i);String entity=reservation.optString("entity",reservation.optString("entity_id",""));String title=reservation.optString("display_title",names.getOrDefault(entity,entity)+" · 会面预留");int slot=reservation.optInt("slot",-1);label((slot>=0?GameDate.label(slot)+"\n":"")+title,16);label("先看游戏提示：可以升级就继续；还需加深关系就作为补充会面。结束后按实际等级重新安排。",14);count++;}
  if(count==0)label("先按下面的会面预留或补充提示继续，完成后记录实际结果。",14);

  JSONArray milestones=plan.optJSONArray("story_milestones");if(milestones!=null&&milestones.length()>0){label("主线目标",20);for(int i=0;i<Math.min(3,milestones.length());i++){JSONObject event=milestones.getJSONObject(i);label((event.isNull("expected_date")?"后续剧情":event.getString("expected_date"))+" · "+event.getString("display_title"),15);label(event.optString("source_description","完成对应剧情后核对实际等级"),13);}}
  JSONArray towerChoices=plan.optJSONArray("dungeon_candidates");if(towerChoices!=null&&towerChoices.length()>0){label("可选爬塔夜",20);label("不预估爬塔收入或楼层。预留前检查阶段次数，出发时再确认游戏是否允许。",13);List<JSONObject> sorted=new ArrayList<>();for(int i=0;i<towerChoices.length();i++)sorted.add(towerChoices.getJSONObject(i));sorted.sort(Comparator.comparingInt(a->a.optInt("slot")));for(int i=0;i<Math.min(3,sorted.size());i++){JSONObject candidate=sorted.get(i);button("预留 "+GameDate.label(candidate.getInt("slot"))+" 爬塔",()->reserveTower(candidate));}}
  JSONArray alternatives=plan.optJSONArray("conditional_activity_candidates");if(alternatives!=null&&alternatives.length()>0){label("待确认的训练与打工备选",20);label("这些时段尚未核对，不计入目标进度或资金。游戏内确认可进行后，更新实际状态再规划。",14);for(int i=0;i<Math.min(3,alternatives.length());i++){JSONObject option=alternatives.getJSONObject(i);label(GameDate.label(option.getInt("slot"))+" · "+option.optString("display_title","待确认行动")+"\n费用 "+option.optInt("yen_cost",0)+" 日元 · 尚未计入收益",15);button("查看这个备选的条件",()->new AlertDialog.Builder(this).setTitle("待确认备选").setMessage(actionDetails(plan,option.optString("action_id"),option)).setPositiveButton("关闭",null).show());}}
  JSONObject pins=preferences==null?null:preferences.getJSONObject("constraints").optJSONObject("pinned_actions");if(pins!=null&&pins.length()>0)button("清除手动预留，重新安排",()->{try{JSONObject constraints=new JSONObject(preferences.getJSONObject("constraints").toString()).put("pinned_actions",new JSONObject());submit("/api/preferences",envelope().put("goals",preferences.getJSONArray("goals")).put("constraints",constraints));}catch(Exception e){notice.setText(e.getMessage());}});
  button("查看条件与证据说明",()->new AlertDialog.Builder(this).setTitle("本次候选的条件").setMessage(planDetails(plan)).setPositiveButton("关闭",null).show());
 }
 private void reserveTower(JSONObject candidate){try{JSONObject constraints=new JSONObject(preferences.getJSONObject("constraints").toString()),pins=constraints.optJSONObject("pinned_actions");pins=pins==null?new JSONObject():new JSONObject(pins.toString());pins.put(""+candidate.getInt("slot"),candidate.getString("action_id"));constraints.put("pinned_actions",pins);JSONObject body=envelope().put("goals",preferences.getJSONArray("goals")).put("constraints",constraints);new AlertDialog.Builder(this).setMessage("预留这个晚上探索？会重新安排冲突的行动，出发前仍需在游戏内确认。").setPositiveButton("预留并重排",(d,w)->submit("/api/preferences",body)).setNegativeButton("取消",null).show();}catch(Exception e){notice.setText(e.getMessage());}}
 private String planDetails(JSONObject plan){StringBuilder text=new StringBuilder("按已核对的基础规则估计，不预设好感加成或爬塔收益。会面预留不提前记作升级。\n");for(String key:new String[]{"explanations","diagnostics"}){JSONArray entries=plan.optJSONArray(key);if(entries==null)continue;for(int i=0;i<entries.length();i++){Object value=entries.opt(i);String message=value instanceof JSONObject?((JSONObject)value).optString("message",""):String.valueOf(value);if(!message.isEmpty())text.append("\n• ").append(message);}}JSONArray steps=plan.optJSONArray("steps");Set<String> shown=new HashSet<>();if(steps!=null)for(int i=0;i<steps.length();i++){JSONObject step=steps.optJSONObject(i);if(step==null)continue;String id=step.optString("action_id");if(id.equals("__wait__")||!shown.add(id))continue;text.append("\n\n").append(actionDetails(plan,id,null));}return text.toString();}
 @Override protected void onDestroy(){destroyed=true;if(coordinator!=null&&!worker.isShutdown())worker.execute(coordinator::close);worker.shutdown();super.onDestroy();}
 static String conditionLabel(String key){switch(key){case "calendar.slotState":return "确认当天该时段没有被剧情占用，且仍可行动";case "calendar.exactDateActionAvailable":return "确认当天该地点营业，且能选择此行动";case "storyFlags.christmasAllInvitationsDeclined":return "确认圣诞邀请已全部婉拒，此时段可自由行动";case "jan21_conditional_story_event_resolved":return "确认1月21日相关剧情已处理，当前时段可自由行动";default:return "需要在游戏内核对的条件："+key;}}
 static String actionDetails(JSONObject plan,String id,JSONObject reservation){
  JSONObject all=plan.optJSONObject("action_metadata"),meta=reservation!=null&&reservation.has("forecast_credit")?reservation:all==null?null:all.optJSONObject(id);if(meta==null)meta=reservation;if(meta==null)return "此行动条件尚未提供，请先核对游戏内是否可进行。";
  StringBuilder out=new StringBuilder(meta.optString("display_title",meta.optString("title","行动条件")));
  if(meta.has("forecast_credit")&&!meta.optBoolean("forecast_credit")){out.append("\n• 这是待确认的备选，不计入预计目标或资金。");out.append("\n• 费用 ").append(meta.optInt("yen_cost",0)).append(" 日元；还需核对当时余额是否足够。");JSONArray conditions=meta.optJSONArray("conditions_to_confirm");if(conditions!=null)for(int i=0;i<conditions.length();i++)out.append("\n• ").append(conditionLabel(conditions.optString(i)));}JSONArray assumptions=meta.optJSONArray("assumptions");if(assumptions!=null)for(int i=0;i<assumptions.length();i++){String key=assumptions.optString(i);String value;switch(key){case "A.calendar_context_complete_enough":value="该日期来自攻略的可用记录，但尚未确认你的剧情分支是否占用此时段；出发前须核对。";break;case "A.complete_rank_event_resolution":case "A.complete_introduction_event_resolution":value="须完整完成本次事件；中途退出或分支变化后应填写实际结果。";break;case "A.source_max_base_points_forecast_only":value="此候选使用了最高基础选项得分假设，不能视为保守保证。";break;default:value="额外条件待核对："+key;}out.append("\n• ").append(value);}
  if(meta.optBoolean("future_routine_availability_assumed"))out.append("\n• 未来营业和空闲时段属于条件预测；尚未确认的时段不能算作安全收益。");
  if(meta.optBoolean("before_entry_check_required"))out.append("\n• 出发前确认塔入口开放；不预估收入或达到楼层。");
  if(meta.optBoolean("income_only_projection"))out.append("\n• 仅计算来源支持的最低工资；实际余额以行动后填写为准。");
  JSONObject gain=meta.optJSONObject("event_gain");if(gain!=null)out.append("\n• 好感采用基础下界，不计 Persona 等加成；来源外文选项序号不是中文选项指引。");
  String source=meta.optString("source_event",meta.optString("source_action_id",meta.optString("source_rule_id","")));if(!source.isEmpty())out.append("\n规则记录：").append(source);
  return out.toString();
 }

